# For demo4: identify the main figure (largest comp) and for each singleton whose color equals the figure's accent,
# find which TR maximizes overlap between predicted painted cells (cells painted under plain placement, O==bg) and actual changes.
# Then verify exact reconstruction.

def solve(I):
    I=np.array(I); R,C=I.shape
    vals,counts=np.unique(I,return_counts=True); bg=int(vals[counts.argmax()])
    cs=comps_of(I,bg)
    figs=[sorted(c) for c in cs if len(c)>1]; singles=[c[0] for c in cs if len(c)==1]
    fg=max(figs,key=len)
    cnt=Counter(int(I[p]) for p in fg)
    acc=[v for v,n in cnt.items() if n==1][0]
    anch=[p for p in fg if int(I[p])==acc][0]
    offs=[(r-anch[0],c-anch[1]) for r,c in fg]
    O=I.copy()
    # per-marker candidate placement scores vs OUTPUT changes
    added=set(map(tuple,np.argwhere((O!=I)&(O==bg))))
    for s in singles:
        r,c=s
        if int(I[r,c])!=acc or (r,c) in set(fg): continue
