        for tn,trf in TR.items():
            pred=set()
            for dr,dc in offs:
                rr,cc=r+trf(dr,dc)[0], c+trf(dr,dc)[1]
                if 0<=rr<R and 0<=cc<C and int(I[rr][cc])==bg:
                    pred.add((rr,cc))
            sc=len(pred&added)
            if best is None or sc>best[0]:
                best=(sc,pred)
        for dr,dc in offs:
            rr,cc=r+best[1].__iter__()
            break
        # place using best transform
        for dr,dc in offs:
            rr,cc=r+best[0](dr,dc)[0], c+best[0](dr,dc)[1]
            if 0<=rr<R and 0<=cc<C and int(I[rr][cc])==bg:
                O[rr][cc]=int(I[fg[0]][fg[0]])
    return O

