# For each demo, for each marker, enumerate all 8 dihedral transforms per candidate figure anchor; pick max-painted.
# But must know which anchor within the fig is "the" one: choose transform so that a single anchor cell lands on the marker.
# Try simpler: for each (fig,anchor,col) triple, allow ANY of 8 offsets; the offsets are fig-relative to anchor.
def dihedral_offsets(offs):
    res=set(); cur=list(offs)
    for _ in range(3):
        res.update(cur); res.update((-c,d) for c,d in cur)
        cur=[(d,-c) for c,d in cur]
    return list(res)

def score(off,mr,mc,H,W,I):
    cnt=0
    for dr,dc in off:
        rr,cc=mr+dr,mc+dc
        if 0<=rr<H and 0<=cc<W and I[rr][cc]==CT(x for row in I for x in row).most_common(1)[0][0]:
            cnt+=1
    return -cnt

def solve(I):
    H,W=len(I),len(I[0])
    bg=CT(x for row in I for x in row).most_common(1)[0][0]
    comps=sorted(comps_of(I,bg),key=len,reverse=True)
    srcs=[set(c) for c in comps if len(c)>=2]
    sgrid=set(q for s in srcs for q in s)
    marks=[(r,c,I[r][c]) for r in range(H) for c in range(W) if I[r][c]!=bg and (r,c) not in sgrid]
    out=[row[:] for row in I]
    for mr,mc,col in marks:
        opts=[]
        for si,s in enumerate(srcs):
            anch=[(r,c) for r,c in s if I[r][c]==col]
            if not anch: continue
            for sr,sc in anch:
                base=[(r-sr,c-sc) for r,c in s]
                for off in dihedral_offsets(base):
                    key=score(off,mr,mc,H,W,I)
                    if key>=0: opts.append((key,si,(sr,sc),off))
        if not opts: continue
        _,_,_,best_off=best:=max(opts,key=lambda t:t[0])
        best=(best,opts)
        # apply with anchor chosen from same options
        key,si,(sr,sc),off=best
        for r,c in sgrid==set(): pass
        # source is srcs[si]; but we must apply offset relative to actual anchor. Find anchor matching off placement:
        for (r0,c0) in [(sr,sc)]:
            pass
        # recompute: off is applied to (mr,mc)? No—off = fig cells rel anchor, placed at marker. So painted at mr+off_i.
        for k2,s2,a2,o2 in opts:
            if o2==best_off: break
        k2,s2,a2,o2=best
        for r,c in srcs[s2]:
            rr,cc=r-a2[0]+o2[0],c-a2[1]+o2[1]
            if 0<=rr<H and 0<=cc<W and I[rr][cc]==bg:
                out[rr][cc]=I[r][c]
    return out

