def trfs(base):
    # 8 dihedral offsets relative to an anchor cell
    res=set(); cur=list(map(tuple,base))
    for _ in range(3):
        res|=set(cur)
        res|={( -c,d) for c,d in cur}
        cur=[(d,-c) for c,d in cur]
    return list(res)

def solve(I):
    H,W=len(I),len(I[0])
    bg=CT(x for row in I for x in row).most_common(1)[0][0]
    comps=sorted(comps_of(I,bg),key=len,reverse=True)
