    marks=[(r,c,I[r][c]) for r in range(H) for c in range(W) if I[r][c]!=bg and (r,c) not in sgrid]
    out=[row[:] for row in I]
    for mr,mc,col in marks:
        opts=[]
        for si,s in enumerate(srcs):
            anch=[(r,c) for r,c in s if I[r][c]==col]
            if not anch: continue
            for sr,sc in anch:
                base=[(r-sr,c-sc) for r,c in s]
                for off in trfs(base):
                    cnt=sum(1 for dr,dc in off
                            if 0<=mr+dr<H and 0<=mc+dc<W and I[mr+dr][mc+dc]==bg)
                    if cnt==0: continue
                    # penalty for partially out-of-grid copies
                    oob=sum(1 for dr,dc in off if not(0<=mr+dr<H and 0<=mc+dc<W))
                    opts.append((cnt,-oob,si,(sr,sc),off))
        if not opts: continue
        _,_,best_si,best_anchor,best_off=max(opts,key=lambda t:t[:2])
        s=srcs[best_si]; a=(best_anchor)
        for r,c in s:
            rr,cc=r-a[0]+best_off[0],c-a[1]+best_off[1]
            if 0<=rr<H and 0<=cc<W and I[rr][cc]==bg:
                out[rr][cc]=I[r][c]
    return out

